<?php
declare(strict_types=1);
function siteH($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function siteImage(string $value,string $alt,string $class=''):string{return $value?'<img class="'.siteH($class).'" src="'.siteH(commercialImageUrl($value)).'" alt="'.siteH($alt).'" loading="lazy">':'';}
function renderCommercial(array $content,bool $preview=false):string{ob_start();$sections=array_values(array_filter($content['sections'],fn($s)=>$s['enabled']));$nav=['features'=>'Funcionalidades','showcase'=>'Telas','steps'=>'Como funciona','faq'=>'Dúvidas','contact'=>'Contato'];$navUsed=[];$contactSection=null;foreach($sections as $candidate)if($candidate['type']==='contact'){$contactSection=$candidate;break;}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="<?=siteH($content['description'])?>"><meta name="theme-color" content="<?=siteH($content['color'])?>"><title><?=siteH($content['title'])?></title><link rel="stylesheet" href="/commercial/site.css"></head><body style="--accent:<?=siteH($content['color'])?>"><?php if($preview):?><div class="preview-notice">Prévia do site · alterações ainda não publicadas</div><?php endif?><header class="site-header"><div class="site-container header-content"><a href="#" class="brand" aria-label="<?=siteH($content['brand'])?> · início"><img src="<?=siteH(commercialImageUrl($content['logo']??'/workspace/logo-trajetoria.png'))?>" alt="<?=siteH($content['brand'])?>"><span><?=siteH($content['tagline'])?></span></a><nav aria-label="Navegação principal"><?php foreach($sections as $s)if(isset($nav[$s['type']])&&!isset($navUsed[$s['type']])): $navUsed[$s['type']]=true;?><a href="#<?=siteH($s['id'])?>"><?=siteH($nav[$s['type']])?></a><?php endif?></nav><a class="access-button" href="/login" <?= $preview?'target="_blank" rel="noopener"':''?>>Acessar <span aria-hidden="true">↗</span></a></div></header><main><?php foreach($sections as $s):$type=$s['type'];$items=$s['items']??[];?><section id="<?=siteH($s['id'])?>" class="site-section section-<?=siteH($type)?>"><div class="site-container"><?php if($type==='hero'):?><div class="hero-grid"><div><p class="eyebrow"><?=siteH($s['eyebrow'])?></p><h1><?=siteH($s['title'])?></h1><p class="hero-description"><?=nl2br(siteH($s['body']))?></p><div class="hero-links"><?php if($s['buttonLabel']&&$s['buttonHref']):?><a class="site-button" href="<?=siteH($s['buttonHref'])?>"><?=siteH($s['buttonLabel'])?> <span>→</span></a><?php endif?><?php if($contactSection):?><a class="text-link" href="#<?=siteH($contactSection['id'])?>">Converse com a equipe ↗</a><?php endif?></div><div class="hero-points"><?php foreach($items as $item):?><div><span class="check">✓</span><b><?=siteH($item['title'])?></b><small><?=siteH($item['body'])?></small></div><?php endforeach?></div></div><div class="hero-visual"><div class="visual-label"><span class="live-dot"></span> Uma visão de cada trajetória</div><div class="screen-shell"><div class="screen-toolbar"><span></span><span></span><span></span><small>TRAJETÓRIA · DEMONSTRAÇÃO</small></div><?=siteCarousel(array_merge([['image'=>$s['image'],'title'=>'Carreira individual','body'=>'Dados fictícios de demonstração']],$items),true)?></div><div class="floating-note"><span>↗</span><div><b>Do registro à evolução.</b><small>Cada matrícula com sua história.</small></div></div></div></div><?php else:?><div class="section-intro"><p class="eyebrow"><?=siteH($s['eyebrow'])?></p><h2><?=siteH($s['title'])?></h2><p><?=nl2br(siteH($s['body']))?></p></div><?php if($s['image']&&$type!=='text')echo siteImage($s['image'],$s['title'],'section-cover');if(in_array($type,['benefits','features','steps'])):?><div class="content-grid grid-<?=siteH($type)?>"><?php foreach($items as $i=>$item):?><article class="feature-card"><span class="card-index"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><h3><?=siteH($item['title'])?></h3><p><?=nl2br(siteH($item['body']))?></p><?=siteImage($item['image']??'',$item['title'])?></article><?php endforeach?></div><?php elseif($type==='showcase'):?><?=siteCarousel($items,false)?><?php elseif($type==='faq'):?><div class="faq-list"><?php foreach($items as $item):?><details><summary><?=siteH($item['title'])?><span aria-hidden="true">+</span></summary><p><?=nl2br(siteH($item['body']))?></p><?=siteImage($item['image']??'',$item['title'])?></details><?php endforeach?></div><?php elseif($type==='contact'):?><form class="contact-form" data-contact-form><div class="form-grid"><label>Seu nome<input name="name" required maxlength="120" autocomplete="name"></label><label>E-mail de contato<input name="email" type="email" required maxlength="190" autocomplete="email"></label><label>Município / órgão<input name="municipality" required maxlength="150" autocomplete="organization"></label><label>Cargo / função (opcional)<input name="role" maxlength="100"></label><label class="form-wide">Telefone (opcional)<input name="phone" type="tel" maxlength="30" autocomplete="tel"></label><label class="form-wide">Como podemos ajudar?<textarea name="message" required maxlength="2000" rows="4"></textarea></label></div><label class="honeypot" aria-hidden="true">Seu site<input name="website" tabindex="-1" autocomplete="off"></label><label class="contact-consent"><input type="checkbox" name="consent" required> Autorizo o uso dos dados informados para retorno sobre esta solicitação.</label><p class="form-note">Seus dados serão acessíveis apenas à administração do Trajetória para tratar esta mensagem. Não envie documentos pessoais nem dados de servidores.</p><p class="contact-result" role="status" aria-live="polite"></p><button class="site-button" <?=$preview?'disabled':''?>><?=siteH($s['buttonLabel']?:'Enviar mensagem')?> <span>→</span></button></form><?php else:?><?=siteImage($s['image'],$s['title'],'text-section-image')?><?php endif?><?php if($type!=='contact'&&$s['buttonLabel']&&$s['buttonHref']):?><p class="section-cta"><a class="site-button" href="<?=siteH($s['buttonHref'])?>"><?=siteH($s['buttonLabel'])?> →</a></p><?php endif?><?php endif?></div></section><?php endforeach?></main><footer class="site-footer"><div class="site-container"><a href="#" class="footer-brand"><?=siteH($content['brand'])?> <span>↗</span></a><p><?=siteH($content['footer'])?></p><a href="/login">Acessar o sistema →</a></div></footer><script>window.COMMERCIAL_PREVIEW=<?=$preview?'true':'false'?>;</script><script src="/commercial/site.js"></script></body></html><?php return (string)ob_get_clean();}

function siteCarousel(array $items,bool $hero=false):string{
 $seen=[];$slides=[];foreach($items as $item){$image=$item['image']??'';if(!$image||isset($seen[$image]))continue;$seen[$image]=true;$slides[]=$item;}if(!$slides)return '';
 $html='<div class="image-carousel '.($hero?'hero-carousel':'showcase-carousel').'" data-carousel role="region" aria-roledescription="carrossel" aria-label="Telas demonstrativas do Trajetória"><div class="carousel-track" tabindex="0">';foreach($slides as $i=>$item){$html.='<article class="carousel-slide" role="group" aria-roledescription="slide" aria-label="'.($i+1).' de '.count($slides).'">'.siteImage($item['image'],$item['title'],$hero?'hero-screen':'showcase-screen');if(!$hero)$html.='<h3>'.siteH($item['title']).'</h3><p>'.siteH($item['body']).'</p><small class="demo-caption">Tela da demonstração · dados fictícios</small>';$html.='</article>';}$html.='</div><div class="carousel-controls"><button type="button" data-carousel-prev aria-label="Tela anterior">←</button><div class="carousel-dots">';foreach($slides as $i=>$item)$html.='<button type="button" data-carousel-dot="'.$i.'" aria-label="Ver tela '.($i+1).' · '.siteH($item['title']).'" '.($i===0?'aria-current="true"':'').'></button>';$html.='</div><button type="button" data-carousel-next aria-label="Próxima tela">→</button><span class="carousel-counter" aria-live="polite">1 / '.count($slides).'</span></div></div>';return $html;
}
